changeSet.sql:
CREATE TABLE IF NOT EXISTS ai_vectors (
                                          id BIGSERIAL PRIMARY KEY,
                                          content_chunk TEXT NOT NULL,
                                          embedding vector(1536),
                                          metadata JSONB,
                                          source_type VARCHAR(50),
                                          source_id BIGINT,
                                          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                          updated_at TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_ai_vectors_source ON ai_vectors(source_type, source_id);
CREATE INDEX IF NOT EXISTS idx_ai_vectors_metadata ON ai_vectors USING gin (metadata);
